    Bug 1962931 - Move focus back to message pane and restore scroll position after light/dark toggle. r=mkmelin



    ### How to test

    - Have your OS or Thunderbird in Dark mode.
    - Load a long message that can be scrolled.
    - Scroll the message.
    - Click on the dark reader toggle in the message header.
    - The message should switch to light mode and the scrolling positon should be restored.
    - Without clicking anywhere else, using the arrow keys should scroll the message.

    Differential Revision: https://phabricator.services.mozilla.com/D256077

diff --git a/mail/base/content/aboutMessage.js b/mail/base/content/aboutMessage.js
index 0d0f36c0c86..7436532ddb0 100644
--- a/mail/base/content/aboutMessage.js
+++ b/mail/base/content/aboutMessage.js
@@ -46,6 +46,7 @@ const prefersDarkQuery = window.matchMedia("(prefers-color-scheme: dark)");
 var gMessage, gMessageURI;
 var autodetectCharset;

+let messageScrolled = 0;
 let reloadTimeout = null;
 function timeoutReload() {
   if (reloadTimeout) {
@@ -205,6 +206,8 @@ window.addEventListener("DOMContentLoaded", event => {
       : "dark-message-mode-toggle-enabled"
   );
   disableDarkReaderToggle.addEventListener("click", e => {
+    const messagePane = getMessagePaneBrowser();
+    messageScrolled = messagePane.contentDocument.documentElement.scrollTop;
     Services.prefs.setBoolPref("mail.dark-reader.enabled", !e.target.checked);
     document.l10n.setAttributes(
       disableDarkReaderToggle,
@@ -212,6 +215,7 @@ window.addEventListener("DOMContentLoaded", event => {
         ? "dark-message-mode-toggle-disabled"
         : "dark-message-mode-toggle-enabled"
     );
+    messagePane.focus();
   });
 });

@@ -463,6 +467,14 @@ var msgObserver = {
         if (prefersDarkQuery.matches) {
           adaptMessageForDarkMode(getMessagePaneBrowser());
         }
+        // Restore the scroll position of a message if it gets reloaded.
+        if (messageScrolled) {
+          getMessagePaneBrowser().contentDocument.documentElement.scrollTo({
+            top: messageScrolled,
+            behavior: "instant",
+          });
+          messageScrolled = 0;
+        }
         break;
       case "change":
         timeoutReload();
diff --git a/mail/test/browser/message-reader/browser_darkReader.js b/mail/test/browser/message-reader/browser_darkReader.js
index 713083ac6b3..192176205f4 100644
--- a/mail/test/browser/message-reader/browser_darkReader.js
+++ b/mail/test/browser/message-reader/browser_darkReader.js
@@ -180,11 +180,55 @@ add_task(async function test_message_header_toggle() {
   EventUtils.synthesizeKey("KEY_Escape", {}, aboutMessage);
   await BrowserTestUtils.waitForPopupEvent(panel, "hidden");

-  info(`Synthesizing mouse click on dark reader toggle`);
+  info("Synthesizing mouse click on dark reader toggle");
   msgLoaded = BrowserTestUtils.waitForEvent(aboutMessage, "MsgLoaded");
   EventUtils.synthesizeMouseAtCenter(toggle, {}, aboutMessage);
   await msgLoaded;
-  info(`Message loaded after switching reader mode`);
+  info("Message loaded after switching reader mode");
+
+  await assert_light_style();
+});
+
+add_task(async function test_message_scroll_position() {
+  info("Enable dark message mode.");
+  let msgLoaded = BrowserTestUtils.waitForEvent(aboutMessage, "MsgLoaded");
+  await toggle_dark_reader(true);
+  await msgLoaded;
+
+  info("Scroll the message body.");
+  aboutMessage
+    .getMessagePaneBrowser()
+    .contentDocument.documentElement.scrollTo({
+      top: 143,
+      behavior: "instant",
+    });
+  await BrowserTestUtils.waitForCondition(
+    () =>
+      aboutMessage.getMessagePaneBrowser().contentDocument.documentElement
+        .scrollTop === 143,
+    "The message should have been scrolled to the wanted position"
+  );
+
+  info("Synthesizing mouse click on dark reader toggle");
+  msgLoaded = BrowserTestUtils.waitForEvent(aboutMessage, "MsgLoaded");
+  EventUtils.synthesizeMouseAtCenter(
+    aboutMessage.document.getElementById("darkReaderToggle"),
+    {},
+    aboutMessage
+  );
+  await msgLoaded;
+
+  await BrowserTestUtils.waitForCondition(
+    () =>
+      aboutMessage.getMessagePaneBrowser().contentDocument.documentElement
+        .scrollTop === 143,
+    "The message should have been scrolled to its original position"
+  );
+  Assert.equal(
+    aboutMessage.document.activeElement,
+    aboutMessage.getMessagePaneBrowser(),
+    "The focus should be on the message browser"
+  );

   await assert_light_style();
 });
